---
import Layout from '../../layouts/Layout.astro';
import SoftwareCard from '../../components/SoftwareCard.astro';
import { categories, getSoftwareByCategory } from '../../data/software';

const { category } = Astro.params;

// Find the category name from the slug
const categoryName = categories.find(cat => 
	cat.toLowerCase().replace(' ', '-') === category
);

if (!categoryName) {
	return Astro.redirect('/categories');
}

const softwareList = getSoftwareByCategory(categoryName);
---

<Layout title={`${categoryName} Alternatives - Open Source Software`}>
